#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<vector<long long>> trips(n, vector<long long>(3));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 3; j++) {
            cin >> trips[i][j];
        }
    }

    vector<pair<long long, long long>> events;
    for (const vector<long long>& t : trips) {
        events.push_back({t[1], t[0]});
        events.push_back({t[2], -t[0]});
    }
    sort(events.begin(), events.end());
    long long load = 0, peak = 0;
    for (const pair<long long, long long>& ev : events) {
        load += ev.second;
        peak = max(peak, load);
    }
    cout << peak << "\n";

    return 0;
}

