import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[][] trips = new long[(int) n][3];
        for (int i = 0; i < trips.length; i++) {
            for (int j = 0; j < trips[i].length; j++) {
                trips[i][j] = Long.parseLong(next());
            }
        }

        int count = (int) n;
        long[] keys = new long[2 * count];
        for (int i = 0; i < count; i++) {
            keys[2 * i] = (((trips[i][1] * 2 + 1) << 16) | i);
            keys[2 * i + 1] = (((trips[i][2] * 2) << 16) | i);
        }
        Arrays.sort(keys);
        long load = 0, peak = 0;
        for (int k = 0; k < 2 * count; k++) {
            int i = (int) (keys[k] & 65535L);
            long type = (keys[k] >> 16) & 1L;
            if (type == 1) load += trips[i][0];
            else load -= trips[i][0];
            peak = Math.max(peak, load);
        }
        System.out.println(peak);
    }
}
